<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bug Evidence Triage Board</title>
<style>
:root{
  --bg:#f6f7f2;--card:#fffef8;--ink:#1d241f;--muted:#667064;
  --line:#d8decf;--accent:#476b4f;--soft:#e8efe3;--bad:#8b2f2f;
  --warn:#8a641f;--good:#2f6840;
}
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink)}
.wrap{max-width:920px;margin:0 auto;padding:14px}
header{padding:12px 0 8px}
h1{font-size:1.35rem;margin:0 0 4px}
p{margin:0;color:var(--muted);line-height:1.35}
.panel,.card,.lane{background:var(--card);border:1px solid var(--line);border-radius:16px;box-shadow:0 1px 0 rgba(0,0,0,.03)}
.panel{padding:12px;margin:10px 0}
textarea,input,select,button{
  width:100%;font:inherit;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--ink)
}
