<body>
<div class="wrap">
<header>
  <h1>Bug Evidence Triage Board</h1>
  <p>Paste messy QA notes, split them into evidence cards, sort each card, then copy a tight bug report.</p>
</header>

<section class="panel">
  <label class="small" for="raw">Messy QA notes</label>
  <textarea id="raw" placeholder="Paste repro notes, screenshots mentioned, browser/device, expected/actual behavior, logs, severity clues..."></textarea>
  <div class="actions">
    <button id="parse">Split into cards</button>
    <button class="secondary" id="sample">Load sample</button>
    <button class="danger" id="clear">Clear</button>
  </div>
</section>

<section class="panel">
  <div class="row">
    <input id="title" placeholder="Bug title">
    <select id="sev">
      <option>Severity: Unset</option>
      <option>Critical</option>
      <option>High</option>
      <option>Medium</option>
      <option>Low</option>
      <option>Cosmetic</option>
    </select>
  </div>
  <div class="row" style="margin-top:8px">
    <input id="env" placeholder="Environment, device, browser, build">
    <input id="owner" placeholder="Area / owner, optional">
  </div>
</section>

<main class="board" id="board"></main>

<section class="panel">
  <div class="actions">
    <button id="build">Build report</button>
    <button class="secondary" id="copy">Copy report</button>
    <button class="secondary" id="download">Download .txt</button>
  </div>
  <pre class="report" id="report"></pre>
</section>
</div>

<script>
const lanes=[
  ["steps","Steps"],
  ["expected","Expected"],
  ["actual","Actual"],
  ["evidence","Evidence"],
  ["severity","Severity"]
];

let cards=JSON.parse(localStorage.bugTriageCards||"[]");
let fields=JSON.parse(localStorage.bugTriageFields||"{}");

const board=document.getElementById("board");
const report=document.getElementById("report");

["title","sev","env","owner"].forEach(id=>{
  const el=document.getElementById(id);
  if(fields[id]) el.value=fields[id];
  el.addEventListener("input",save);
});

function save(){
  localStorage.bugTriageCards=JSON.stringify(cards);
  localStorage.bugTriageFields=JSON.stringify({
    title:title.value,sev:sev.value,env:env.value,owner:owner.value
  });
}

function makeCard(text,lane="evidence"){
  return {id:crypto.randomUUID(),text:text.trim(),lane,tag:"Need review"};
}

function guessLane(t){
  const s=t.toLowerCase();
  if(/step|click|tap|open|login|select|go to|navigate|repro/.test(s)) return "steps";
  if(/expect|should|supposed/.test(s)) return "expected";
  if(/actual|instead|but|fails|broken|error|crash|doesn't|cannot|wrong/.test(s)) return "actual";
  if(/screenshot|video|log|console|network|har|attached|recording/.test(s)) return "evidence";
  if(/critical|high|medium|low|blocker|sev|severity|impact/.test(s)) return "severity";
  return "evidence";
}

function render(){
  board.textContent="";
  lanes.forEach(([key,name])=>{
    const lane=document.createElement("section");
    lane.className="lane";
    lane.dataset.lane=key;

    const h=document.createElement("h2");
    const label=document.createElement("span");
    label.textContent=name;
    const count=document.createElement("span");
    count.className="count";
    count.textContent=cards.filter(c=>c.lane===key).length;
    h.append(label,count);

    const drop=document.createElement("div");
    drop.className="drop";

    cards.filter(c=>c.lane===key).forEach(c=>drop.appendChild(cardEl(c)));

    lane.append(h,drop);
    board.appendChild(lane);
  });
  save();
}

function cardEl(c){
  const el=document.createElement("article");
  el.className="card";
  el.draggable=true;

  const ta=document.createElement("textarea");
  ta.value=c.text;
  ta.addEventListener("input",()=>{c.text=ta.value;save();});

  const meta=document.createElement("div");
  meta.className="meta";

  const sel=document.createElement("select");
  lanes.forEach(([k,n])=>{
    const o=document.createElement("option");
    o.value=k;o.textContent=n;if(c.lane===k)o.selected=true;
    sel.appendChild(o);
  });
  sel.addEventListener("change",()=>{c.lane=sel.value;render();});

  const tag=document.createElement("select");
  ["Need review","Confirmed","Missing proof","Likely duplicate","Weak repro","Ready"].forEach(v=>{
    const o=document.createElement("option");
    o.textContent=v;if(c.tag===v)o.selected=true;
    tag.appendChild(o);
  });
  tag.addEventListener("change",()=>{c.tag=tag.value;save();});

  const chips=document.createElement("div");
  chips.className="chips";
  const chip=document.createElement("span");
  chip.className="chip";
  chip.textContent=c.tag;
  chips.appendChild(chip);

  const del=document.createElement("button");
  del.className="secondary";
  del.textContent="Delete";
  del.addEventListener("click",()=>{cards=cards.filter(x=>x.id!==c.id);render();});

  meta.append(sel,tag);
  el.append(ta,meta,chips,del);
  return el;
}

function grouped(key){
  return cards.filter(c=>c.lane===key&&c.text.trim()).map((c,i)=>`${i+1}. ${c.text.trim()}`);
}

function buildReport(){
  const out=[
    `Title: ${title.value||"Untitled bug"}`,
    `Severity: ${sev.value.replace("Severity: ","")}`,
    env.value?`Environment: ${env.value}`:"",
    owner.value?`Area / Owner: ${owner.value}`:"",
    "",
    "Steps to reproduce:",
    ...(grouped("steps").length?grouped("steps"):["1. TBD"]),
    "",
    "Expected result:",
    ...(grouped("expected").length?grouped("expected"):["TBD"]),
    "",
    "Actual result:",
    ...(grouped("actual").length?grouped("actual"):["TBD"]),
    "",
    "Evidence:",
    ...(grouped("evidence").length?grouped("evidence"):["TBD"]),
    "",
    "Severity / impact notes:",
    ...(grouped("severity").length?grouped("severity"):["TBD"])
  ].filter(x=>x!==null).join("\n");
  report.textContent=out;
}

parse.onclick=()=>{
  const parts=raw.value.split(/\n+|(?<=\.)\s+(?=[A-Z0-9])/).map(x=>x.trim()).filter(Boolean);
  cards=parts.map(t=>makeCard(t,guessLane(t)));
  render();buildReport();
};

sample.onclick=()=>{
  raw.value=`iPhone 15, Safari, staging build 1.8.2
Open checkout, add monthly plan, tap Apply coupon.
Expected total should update after coupon is applied.
Actual total stays the same until page refresh.
Console shows 422 coupon_validation.
Screenshot attached from 2:13 PM.
High impact because paid checkout looks broken.`;
};

clear.onclick=()=>{
  cards=[];report.textContent="";raw.value="";
  ["title","env","owner"].forEach(id=>document.getElementById(id).value="");
  sev.value="Severity: Unset";
  save();render();
};

build.onclick=buildReport;

copy.onclick=async()=>{
  buildReport();
  await navigator.clipboard.writeText(report.textContent);
  copy.textContent="Copied";
  setTimeout(()=>copy.textContent="Copy report",900);
};

download.onclick=()=>{
  buildReport();
  const blob=new Blob([report.textContent],{type:"text/plain"});
  const a=document.createElement("a");
  a.href=URL.createObjectURL(blob);
  a.download="bug-report.txt";
  a.click();
  URL.revokeObjectURL(a.href);
};

render();
buildReport();
</script>
</body>
</html>
